/* Paired, synchronized schedule diagrams, sourced from both GTFS ZIPs. */
(function(){
const ns='http://www.w3.org/2000/svg', select=document.querySelector('#compare-change'), date=document.querySelector('#compare-date'), direction=document.querySelector('#compare-direction'), status=document.querySelector('#comparison-status');
const leftChart=document.querySelector('#compare-original-chart'),rightChart=document.querySelector('#compare-draft-chart');leftChart.addEventListener('scroll',()=>{if(rightChart.scrollLeft!==leftChart.scrollLeft)rightChart.scrollLeft=leftChart.scrollLeft});rightChart.addEventListener('scroll',()=>{if(leftChart.scrollLeft!==rightChart.scrollLeft)leftChart.scrollLeft=rightChart.scrollLeft});
let current=null, expanded=new Set(), loadSerial=0;
const previous=document.querySelector('#compare-prev'),next=document.querySelector('#compare-next'),position=document.querySelector('#compare-position');
function updateNavigation(){const i=select.selectedIndex,n=select.options.length;previous.disabled=i<=0;next.disabled=i<0||i>=n-1;position.textContent=i<0?'No modeled changes':(i+1)+' of '+n+' modeled changes';}
function moveChange(offset){const index=select.selectedIndex+offset;if(index<0||index>=select.options.length)return;select.selectedIndex=index;date.replaceChildren();direction.replaceChildren();updateNavigation();load()}
previous.addEventListener('click',()=>moveChange(-1));next.addEventListener('click',()=>moveChange(1));
const mins=v=>{const m=/^(\d+):(\d{2}):(\d{2})$/.exec(v||'');return m?+m[1]*60+(+m[2])+(+m[3])/60:null};
const fmt=v=>String(Math.floor(v/60)).padStart(2,'0')+':'+String(Math.floor(v%60)).padStart(2,'0');
function svgEl(parent,name,attrs,text){const e=document.createElementNS(ns,name);Object.entries(attrs).forEach(([k,v])=>e.setAttribute(k,v));if(text!==undefined)e.textContent=text;parent.append(e);return e}
function render(){if(!current)return;const mappings=current.mappings, target=new Set(mappings.map(m=>m.station_id));const firstPair=current.pairs.find(p=>p.draft.some(s=>target.has(s.station_id))||p.original.some(s=>target.has(s.station_id)))||current.pairs[0],reference=current.kind==='added_stops'?firstPair.draft:firstPair.original,indices=reference.map((s,i)=>target.has(s.station_id)?i:-1).filter(i=>i>=0);if(!indices.length){status.textContent='No matching station rows in these trips.';return}const lo=Math.max(0,Math.min(...indices)-1),hi=Math.min(reference.length-1,Math.max(...indices)+1),stations=reference.slice(lo,hi+1),lanes=[];
for(const s of stations){const m=mappings.find(x=>x.station_id===s.station_id&&x.current_stop_id&&x.target_stop_id&&x.current_stop_id!==x.target_stop_id);if(m){lanes.push({station:s.station_id,id:m.current_stop_id,label:s.name+' · '+m.current_stop_id,changed:true,role:'original'});lanes.push({station:s.station_id,id:m.target_stop_id,label:s.name+' · '+m.target_stop_id,changed:true,role:'draft'})}else lanes.push({station:s.station_id,id:null,label:s.name,changed:target.has(s.station_id),role:target.has(s.station_id)?(current.kind==='added_stops'?'draft':'original'):null})}
const laneIndex=s=>lanes.findIndex(x=>x.station===s.station_id&&(!x.id||x.id===s.stop_id));const trips=current.pairs.map((p,i)=>{const within=p.original.filter(s=>laneIndex(s)>=0&&mins(s.time)!==null);return {pair:p,first:within.length?mins(within[0].time):null,pattern:p.original.map(s=>s.stop_id).join('|')+'→'+p.draft.map(s=>s.stop_id).join('|'),i}}).filter(t=>t.first!==null).sort((a,b)=>a.first-b.first);let groups=[];for(const t of trips){let last=groups[groups.length-1];if(!last||last.pattern!==t.pattern||t.first-last.end>90){last={id:'p'+groups.length,pattern:t.pattern,start:t.first,end:t.first,trips:[]};groups.push(last)}last.end=t.first;last.trips.push(t)}
const controls=document.querySelector('#compare-patterns');controls.replaceChildren();groups.forEach((g,i)=>{const b=document.createElement('button');b.className='btn';b.style.margin='3px';b.textContent='Pattern '+String.fromCharCode(65+i%26)+' · '+fmt(g.start)+'–'+fmt(g.end)+' · '+g.trips.length+(expanded.has(g.id)?' −':' +');b.setAttribute('aria-pressed',String(expanded.has(g.id)));b.onclick=()=>{expanded.has(g.id)?expanded.delete(g.id):expanded.add(g.id);render()};controls.append(b)});
function chart(side,node){node.replaceChildren();let left=185,right=18,top=40,step=23,x=left,cols=[];for(const g of groups){let w=expanded.has(g.id)?Math.max(260,Math.min(900,(g.end-g.start)*2+110)):190;cols.push({x,w});x+=w}let height=Math.max(170,top+lanes.length*step+55),width=Math.max(470,x+right);const svg=svgEl(node,'svg',{width,height,viewBox:`0 0 ${width} ${height}`,role:'img','aria-label':side==='original'?'Original schedule time-stop diagram':'Draft schedule time-stop diagram'});lanes.forEach((l,i)=>{const y=top+i*step,highlight=l.role===side;if(highlight)svgEl(svg,'rect',{x:0,y:y-10,width:Math.max(width,x+right),height:20,fill:side==='original'?'#fbe9e5':'#e2f4e8'});svgEl(svg,'line',{x1:left,y1:y,x2:x,y2:y,stroke:highlight?(side==='original'?'#db9f91':'#8bbd9c'):'#ececec'});svgEl(svg,'text',{x:left-8,y:y+4,'text-anchor':'end','font-size':10,'font-weight':highlight?'bold':'normal',fill:highlight?(side==='original'?'#8a3024':'#176b35'):'#333'},l.label)});groups.forEach((g,i)=>{const pos=cols[i],isOpen=expanded.has(g.id),scale=(pos.w-30)/Math.max(1,g.end-g.start+90);svgEl(svg,'line',{x1:pos.x,y1:top-14,x2:pos.x,y2:height-45,stroke:'#ccc'});svgEl(svg,'text',{x:pos.x+pos.w/2,y:height-25,'text-anchor':'middle','font-size':10},'Pattern '+String.fromCharCode(65+i%26)+' · '+g.trips.length+' trips');svgEl(svg,'text',{x:pos.x+pos.w/2,y:height-8,'text-anchor':'middle','font-size':10},fmt(g.start)+'–'+fmt(g.end));if(isOpen)for(let tick=Math.ceil(g.start/60)*60;tick<=g.end+60;tick+=60){let tx=pos.x+15+(tick-g.start)*scale;if(tx<=pos.x+pos.w-10)svgEl(svg,'text',{x:tx,y:top-20,'text-anchor':'middle','font-size':10},fmt(tick))}const shown=isOpen?g.trips:[g.trips[Math.floor(g.trips.length/2)]];for(const t of shown){const seq=t.pair[side], points=seq.map(s=>({s,minute:mins(s.time),lane:laneIndex(s)})).filter(p=>p.minute!==null&&p.lane>=0);if(points.length<2)continue;const first=points[0].minute,start=isOpen?pos.x+15+(first-g.start)*scale:pos.x+pos.w/2,factor=isOpen?scale:Math.min(.6,(pos.w/2-10)/Math.max(1,points[points.length-1].minute-first)),xy=p=>[start+(p.minute-first)*factor,top+p.lane*step];const line=svgEl(svg,'polyline',{points:points.map(p=>xy(p).join(',')).join(' '),fill:'none',stroke:side==='original'?'#5c6a7a':'#176b35','stroke-width':isOpen?1:2,opacity:isOpen?.65:1});svgEl(line,'title',{},(side==='original'?t.pair.original_id:t.pair.draft_id));for(const p of points){const [cx,cy]=xy(p),changed=(side==='draft'?(t.pair.draft_changed_sequences||t.pair.changed_sequences):t.pair.changed_sequences).includes(p.s.sequence);const skip=p.s.pickup_type==='1'&&p.s.drop_off_type==='1';let dot;if(skip){dot=svgEl(svg,'g',{});svgEl(dot,'line',{x1:cx-4,y1:cy-4,x2:cx+4,y2:cy+4,stroke:'#a34036','stroke-width':2});svgEl(dot,'line',{x1:cx-4,y1:cy+4,x2:cx+4,y2:cy-4,stroke:'#a34036','stroke-width':2})}else dot=svgEl(svg,'circle',{cx,cy,r:changed?5:2.7,fill:changed?(side==='original'?'#a34036':'#176b35'):'#65756d',stroke:changed?(side==='original'?'#7c241c':'#075729'):'white','stroke-width':changed?1.5:.7});svgEl(dot,'title',{},p.s.name+' · '+p.s.stop_id+' · '+p.s.time+' · pickup_type='+p.s.pickup_type+' · drop_off_type='+p.s.drop_off_type+(skip?' · no pickup or drop-off':'')+' · '+(side==='original'?t.pair.original_id:t.pair.draft_id))}}});node.append(svg)}
chart('original',document.querySelector('#compare-original-chart'));chart('draft',document.querySelector('#compare-draft-chart'));document.querySelector('#comparison-summary').textContent=current.change_id+' · route '+current.route_id+' · direction '+current.direction_id+' · '+current.date+' · '+current.pairs.length+' affected trips';document.querySelector('#comparison-card-id').textContent=current.change_id;document.querySelector('#comparison-alert-summary').textContent=current.alert.split('\n').find(x=>x.trim())||'Service change';document.querySelector('#comparison-alert-text').textContent=current.alert;document.querySelector('#compare-fact-route').textContent=current.route_id;document.querySelector('#compare-fact-trips').textContent=current.pairs.length;const stationNames=[...new Set((current.mappings||[]).map(m=>m.station_name).filter(Boolean))];const stationSummary=stationNames.length?stationNames.join(', '):'the affected stops';let description;if(current.kind==='stops_skipped')description='No pickup or drop-off at '+stationSummary+'.';else if(current.kind==='added_stops')description='Adds stops at '+stationSummary+'.';else if(current.kind==='platform_change')description='Moves boarding at '+stationSummary+' to the other platform.';else description='Schedule changes at '+stationSummary+'.';document.querySelector('#comparison-change-description').textContent=description;const gtfsDetail=current.kind==='stops_skipped'?'stop_times.txt keeps the station rows and sets pickup_type and drop_off_type to 1.':current.kind==='added_stops'?'stop_times.txt adds stop rows with estimated times.':current.kind==='platform_change'?'stop_times.txt changes the platform stop IDs.':'The affected stop records change.';document.querySelector('#comparison-gtfs-detail').textContent=gtfsDetail+' trips.txt and calendar_dates.txt isolate affected service dates; calendar.txt is updated when present.';const estimate=document.querySelector('#comparison-estimate-note');estimate.hidden=current.kind!=='added_stops';estimate.textContent=current.kind==='added_stops'?'Added stop times are estimates.':'';updateNavigation();}
async function load(){if(!select.value)return;const serial=++loadSerial;updateNavigation();status.textContent='Loading the original and draft schedules…';try{const q=new URLSearchParams({change_id:select.value});if(date.value)q.set('date',date.value);if(direction.value)q.set('direction',direction.value);const response=await fetch('/api/change-diagram?'+q);const d=await response.json();if(serial!==loadSerial)return;if(!response.ok)throw Error(d.error||'Could not load schedule');current=d;date.replaceChildren(...d.dates.map(x=>new Option(x,x)));date.value=d.date;direction.replaceChildren(...d.directions.map(x=>new Option('Direction '+x,x)));direction.value=d.direction_id;expanded.clear();render();status.textContent='Comparing change '+d.change_id+' from draft '+d.version+'.';document.querySelector('#comparison-chart-note').textContent=d.note}catch(e){if(serial===loadSerial)status.textContent='Could not load comparison: '+e.message}}
select.addEventListener('change',()=>{updateNavigation();date.replaceChildren();direction.replaceChildren();load()});date.addEventListener('change',()=>{direction.replaceChildren();load()});direction.addEventListener('change',load);document.querySelector('#compare-expand').addEventListener('click',()=>{if(!current)return;const buttons=[...document.querySelector('#compare-patterns').children];if(expanded.size===buttons.length)expanded.clear();else buttons.forEach((_,i)=>expanded.add('p'+i));render()});
window.updateComparison=function(data){const before=select.value;select.replaceChildren(...data.changes.map(c=>new Option(c.change_id+' · '+c.alert.split('\n')[0],c.change_id)));if(data.changes.some(c=>c.change_id===before))select.value=before;date.replaceChildren();direction.replaceChildren();document.querySelector('#comparison-result').hidden=false;updateNavigation();load()};
if(window.pendingComparison){window.updateComparison(window.pendingComparison);delete window.pendingComparison}
})();
